import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and current year `now`.

    Only years are given, so the result is `now - born`. The clock is never
    read; `now` is always supplied by the caller.

    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_age_at_typical() -> None:
    assert age_at(1990, 2024) == 34
    assert age_at(2000, 2001) == 1


def test_age_at_same_year() -> None:
    assert age_at(2024, 2024) == 0


def test_age_at_large_span() -> None:
    assert age_at(1900, 2024) == 124


def test_age_at_negative_years() -> None:
    assert age_at(-100, 50) == 150


def test_age_at_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2024, 2023)
